'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{chromium}=require('playwright');
const root=path.resolve(__dirname,'..'),out=process.env.JY_NAME_REVIEW||path.join(require('node:os').tmpdir(),'jingyue-name-review');fs.mkdirSync(out,{recursive:true});
const types={'.html':'text/html','.js':'text/javascript','.css':'text/css','.svg':'image/svg+xml','.webp':'image/webp','.png':'image/png','.jpeg':'image/jpeg','.jpg':'image/jpeg','.json':'application/json','.woff2':'font/woff2','.mp3':'audio/mpeg'};
async function routes(page,missing){await page.route('**/*',async route=>{const url=new URL(route.request().url());if(url.origin!=='https://jingyue.uk')return route.abort();if(url.pathname.startsWith('/api/'))return route.fulfill({contentType:'application/json',body:JSON.stringify({ok:true,count:1,live:1,total:1})});const file=path.resolve(root,'.'+decodeURIComponent(url.pathname==='/'?'/index.html':url.pathname));if(!file.startsWith(root+path.sep))return route.abort();try{return await route.fulfill({body:fs.readFileSync(file),contentType:types[path.extname(file)]||'application/octet-stream'});}catch(e){missing.push(url.pathname);return route.fulfill({status:404,body:''});}});}
async function layout(page){return page.locator('#nm-room').evaluate(root=>({overflow:root.scrollWidth>innerWidth+1,bad:[...root.querySelectorAll('button,input,textarea,select')].filter(e=>e.getClientRects().length).map(e=>({id:e.id||e.textContent.trim().slice(0,30),r:e.getBoundingClientRect()})).filter(x=>x.r.left<-1||x.r.right>innerWidth+1).map(x=>x.id)}));}
(async()=>{
 const launch=()=>chromium.launch({executablePath:process.env.JY_CHROMIUM||chromium.executablePath(),args:['--no-sandbox','--disable-dev-shm-usage','--enable-unsafe-swiftshader','--use-gl=angle','--use-angle=swiftshader'].concat(process.env.JY_SINGLE_PROCESS?['--no-zygote','--single-process','--in-process-gpu','--disable-crash-reporter']:[])});let browser=null;const report=[];
 try{
  for(const width of (process.env.JY_NAME_WIDTHS?process.env.JY_NAME_WIDTHS.split(',').map(Number):[320,390,768,1440])){
   browser=await launch();
   const context=await browser.newContext({viewport:{width,height:width<800?844:960},serviceWorkers:'block',reducedMotion:'reduce',acceptDownloads:true}),page=await context.newPage(),errors=[],missing=[];
   page.on('pageerror',e=>errors.push(e.message));await routes(page,missing);await page.addInitScript(()=>{window.__nameCopied='';Object.defineProperty(navigator,'clipboard',{value:{writeText:async value=>{window.__nameCopied=value;}}});});await page.goto('https://jingyue.uk',{waitUntil:'load'});await page.locator('.at-name-card').waitFor();
   const banner=await page.locator('.at-name-card').boundingBox(),grid=await page.locator('.at-tools').boundingBox(),last=await page.locator('[data-tool=yijing]').boundingBox();const liuren=await page.locator('.at-liuren-card').boundingBox();assert(Math.abs(banner.width-liuren.width)<2,'name and liuren have matching widths at '+width);assert(Math.abs(banner.y-liuren.y)<2,'paired final row');assert(banner.y>last.y+last.height,'name must follow the existing final card row');assert.equal(await page.locator('.at-tools [data-tool]').count(),14);
   await page.locator('.at-name-card').scrollIntoViewIfNeeded();await page.screenshot({path:path.join(out,'name-home-'+width+'.png')});await page.locator('.at-name-card').click();await page.locator('#nm-surname').fill('歐陽');await page.locator('#nm-given').fill('修');await page.locator('#nm-question').fill('完整分析我的名字，哪些地方適合保留？');
   const before=await layout(page);assert.equal(before.overflow,false);assert.deepEqual(before.bad,[]);await page.screenshot({path:path.join(out,'name-form-'+width+'.png')});
   await page.locator('#nm-prepare').click();await page.locator('#nm-review-form').waitFor();assert.equal(await page.locator('.nm-review-row').count(),3);assert.equal(await page.locator('#nm-stroke-0').inputValue(),'15');await page.screenshot({path:path.join(out,'name-review-'+width+'.png')});await page.locator('#nm-analyze').click();await page.locator('.nm-result-title').waitFor();assert.equal(await page.locator('.nm-school').count(),6);assert.equal(await page.locator('.nm-result-title h2').innerText(),'歐陽修');const result=await page.evaluate(()=>JYNameRoom.getState().result);assert.deepEqual(result.fiveGrids.grids.map(g=>g.num),[32,27,11,16,42]);assert.equal(result.bazi.status,'missing');assert.equal(result.nameGua.status,'complete');
   await page.locator('[data-nm-action=copy]').click();const prompt=await page.evaluate(()=>window.__nameCopied);assert(prompt.includes('歐陽修'));assert(prompt.includes('姓名深入取捨'));assert(prompt.includes('本次資料與記憶邊界'));assert.equal((prompt.match(/願你諸事順遂。/g)||[]).length,1);assert(prompt.endsWith('願你諸事順遂。'));
   const after=await layout(page);assert.equal(after.overflow,false);assert.deepEqual(after.bad,[]);await page.locator('.nm-result-title').scrollIntoViewIfNeeded();await page.screenshot({path:path.join(out,'name-result-'+width+'.png')});await page.locator('[data-nm-action=close]').click();assert.equal(await page.locator('#nm-room').count(),0);assert.equal(await page.evaluate(()=>document.activeElement.getAttribute('data-tool')),'name');assert.notEqual(await page.evaluate(()=>document.body.style.overflow),'hidden');
   // Second opening retains only this page's explicit input and can edit/compare.
   await page.locator('.at-name-card').click();await page.locator('[data-nm-action=edit]').click();await page.locator('#nm-surname').fill('王');await page.locator('[data-nm-mode=compare]').click();await page.locator('#nm-candidates').fill('小明\n安\n源');await page.locator('#nm-prepare').click();await page.locator('#nm-review-form').waitFor();await page.locator('#nm-analyze').click();await page.locator('.nm-compare-table').waitFor();assert.equal(await page.locator('[data-nm-result]').count(),3);await page.locator('[data-nm-result="2"]').click();assert.equal(await page.locator('.nm-result-title h2').innerText(),'王源');assert.equal((await page.evaluate(()=>JYNameRoom.getState().result.names)).length,3);assert.deepEqual((await layout(page)).bad,[]);
   if(width===390){
    await page.locator('[data-nm-action=edit]').click();await page.locator('[data-nm-mode=single]').click();await page.locator('#nm-given').fill('小明');await page.locator('.nm-details').first().locator('summary').click();await page.locator('#nm-birth-date').fill('1983-08-25');await page.locator('#nm-birth-time').fill('14:55');await page.locator('#nm-prepare').click();await page.locator('#nm-review-form').waitFor();await page.locator('#nm-analyze').click();await page.locator('.nm-bazi-pillars').waitFor();assert.deepEqual(await page.locator('.nm-bazi-pillars b').allInnerTexts(),['癸亥','庚申','乙酉','癸未']);assert.equal((await page.evaluate(()=>JYNameRoom.getState().result)).zodiac.zodiac,'豬');
    const downloadPromise=page.waitForEvent('download');await page.locator('[data-nm-action=download]').click();const download=await downloadPromise;assert.equal(download.suggestedFilename(),'jingyue-name-analysis.json');const file=await download.path(),saved=JSON.parse(fs.readFileSync(file,'utf8'));assert.equal(saved.facts.name,'王小明');assert(saved.prompt.includes('14:55'));
    // No user markup is inserted into the UI or executed through the exported question.
    await page.locator('[data-nm-action=edit]').click();await page.locator('#nm-question').fill('</textarea><img id="nm-injected" src=x>');await page.locator('[data-nm-mode=compare]').click();assert.equal(await page.locator('#nm-injected').count(),0);assert.equal(await page.locator('#nm-question').inputValue(),'</textarea><img id="nm-injected" src=x>');
   }
   // Regression: the actual reported original-name question survives review, native result, prompt and download.
   if(await page.locator('#nm-input-form').count()===0)await page.locator('[data-nm-action=edit]').click();await page.locator('[data-nm-mode=compare]').click();await page.locator('#nm-surname').fill('陳');await page.locator('#nm-baseline-name').fill('');await page.locator('#nm-candidates').fill('弘林\n鴻淋\n沐洪\n水扁');await page.locator('#nm-question').fill('那個比現在名字好 現名陳政軒');await page.locator('#nm-purpose').selectOption('rename');
   await page.locator('#nm-prepare').click();await page.locator('#nm-review-form').waitFor();const reviewChars=await page.locator('.nm-glyph').allInnerTexts();assert(reviewChars.includes('政'));assert(reviewChars.includes('軒'));assert.equal(new Set(reviewChars).size,reviewChars.length);assert((await page.locator('.nm-lead').innerText()).includes('陳政軒'));
   await page.locator('#nm-analyze').click();await page.locator('.nm-compare-table').waitFor();const compared=await page.evaluate(()=>JYNameRoom.getState().result);assert.equal(compared.names.length,5);assert.equal(compared.baseline.name,'陳政軒');assert.equal(compared.comparison.pairs.length,4);assert.equal(await page.locator('[data-nm-result]').count(),5);assert.equal(await page.locator('.nm-result-title h2').innerText(),'陳政軒');assert((await page.locator('.nm-compare-table th.nm-baseline-column').innerText()).includes('基準'));
   await page.locator('[data-nm-result="1"]').click();assert.equal(await page.locator('.nm-result-title h2').innerText(),'陳弘林');assert((await page.locator('.nm-reference-summary').innerText()).includes('人格 24 → 21'));assert.deepEqual((await layout(page)).bad,[]);assert.equal((await layout(page)).overflow,false);await page.screenshot({path:path.join(out,'name-original-compare-'+width+'.png')});
   await page.locator('[data-nm-action=copy]').click();const originalPrompt=await page.evaluate(()=>window.__nameCopied);assert(originalPrompt.includes('已提供並實算比較基準：陳政軒'));assert(originalPrompt.includes('必答對照：陳沐洪 ↔ 陳政軒'));assert(!originalPrompt.includes('那個比名字好'));assert.equal((originalPrompt.match(/願你諸事順遂。/g)||[]).length,1);
   const compareDownloadPromise=page.waitForEvent('download');await page.locator('[data-nm-action=download]').click();const compareDownload=await compareDownloadPromise,compareSaved=JSON.parse(fs.readFileSync(await compareDownload.path(),'utf8'));assert.equal(compareSaved.facts.baseline.name,'陳政軒');assert.equal(compareSaved.facts.names.length,5);
   // Explicit baseline also works in single-name mode, and disagreement is actionable before analysis.
   await page.locator('[data-nm-action=edit]').click();await page.locator('[data-nm-mode=single]').click();await page.locator('#nm-given').fill('弘林');await page.locator('#nm-baseline-name').fill('陳政軒');await page.locator('#nm-question').fill('是否值得改名？');await page.locator('#nm-prepare').click();await page.locator('#nm-review-form').waitFor();await page.locator('#nm-analyze').click();await page.locator('.nm-compare-table').waitFor();assert.equal(await page.locator('[data-nm-result]').count(),2);
   await page.locator('[data-nm-action=edit]').click();await page.locator('#nm-question').fill('與現名陳沐洪比較');await page.locator('#nm-prepare').click();await page.locator('#nm-error').waitFor({state:'visible'});assert((await page.locator('#nm-error').innerText()).includes('不一致'));assert.equal(await page.locator('#nm-review-form').count(),0);
   await page.keyboard.press('Escape');assert.equal(await page.locator('#nm-room').count(),0);assert.deepEqual(errors,[],'page errors at '+width);assert.deepEqual(missing,[],'missing assets at '+width);report.push({width,fullRow:true,form:before,result:after,errors,missing});await context.close();await browser.close();browser=null;console.log('PASS '+width+'px: paired portrait entrance, complete flow, native data, copy, comparison and restored focus');
  }
  fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(report,null,2));
 }finally{if(browser)await browser.close();}
})().catch(error=>{console.error(error.stack);process.exitCode=1;});
